import os, re, subprocess, sys

tracked = [p for p in subprocess.check_output(['git', 'ls-files', '-z']).decode('utf-8', 'surrogateescape').split('\0') if p]
renames_files = [p for p in tracked if os.path.basename(p) == 'renames.conf']
if not renames_files:
    sys.exit(1)
rf = next((p for p in renames_files if p == 'config/renames.conf'), renames_files[0])
mapping = dict()
try:
    with open(rf, 'r', encoding='utf-8', errors='surrogateescape', newline='') as f:
        for line in f:
            s = line.strip()
            if not s or s.startswith('#') or '=' not in s:
                continue
            old, new = s.split('=', 1)
            old, new = old.strip(), new.strip()
            if old and new:
                mapping[old] = new
except OSError:
    sys.exit(1)

config_dir = os.path.dirname(rf)

def key_of(line):
    m = re.match(r'^\s*([^\s=:#]+)\s*[=:]\s*', line)
    return m.group(1) if m else None

config_exts = ['.conf', '.cfg', '.ini', '.toml', '.yaml', '.yml', '.json', '.properties', '.env']

changed = []
for path in tracked:
    if path == rf:
        continue
    if config_dir:
        if not path.startswith(config_dir + '/'):
            continue
    else:
        if os.path.splitext(path)[1].lower() not in config_exts:
            continue
    try:
        with open(path, 'r', encoding='utf-8', errors='surrogateescape', newline='') as f:
            lines = f.readlines()
    except (OSError, UnicodeError):
        continue
    keys = set(key_of(l) for l in lines)
    new_lines = []
    removed = False
    for line in lines:
        k = key_of(line)
        if k in mapping and mapping[k] in keys:
            removed = True
            continue
        new_lines.append(line)
    if removed and new_lines != lines:
        with open(path, 'w', encoding='utf-8', errors='surrogateescape', newline='') as f:
            f.writelines(new_lines)
        changed.append(path)

if not changed:
    sys.exit(1)
print('dropped old keys from:', ', '.join(changed))
